def _comps(g,bg):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for r in range(R):
        for c in range(C):
            if seen[r][c] or g[r][c]==bg: continue
            col=g[r][c]; st=[(r,c)]; seen[r][c]=True; cells=[]
            while st:
                x,y=st.pop(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<R and 0<=ny<C and not seen[nx][ny] and g[nx][ny]==col:
                        seen[nx][ny]=True; st.append((nx,ny))
            out.append((col,cells))
    return out

