    n=len(cells)
    if n<3: return (False,None,0,0)
    S=set(cells)
    for (jr,jc) in S:
        if (jr,rmin if rs.count(jr)>1 else 0) : pass
    # find joint: cell whose removal... simpler: try each cell as joint; vertical arm = same column, horizontal arm = same row
    best=None
    for (jr,jc) in S:
        vert=[(r,c) for (r,c) in S if c==jc]
        hor =[(r,c) for (r,c) in S if r==jr]
        if len(vert)+len(hor)-1==n and len(vert)>=2 and len(hor)>=2:
            armup = any(r<jr for r,c in vert)
            rright= any(c>jc for r,c in hor)
            best=(True,(jr,jc),len(vert),len(hor),armup,rright)
            break
    if best: return (True,best[1],best[2],best[3],best[4],best[5])
